#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>

#define BLOCK 512
#define PAYLOAD (BLOCK - 12)

typedef struct { int txid; char kind[4]; int block_num; char data[PAYLOAD]; } Record;

static void write_record(int fd, Record *r) {
    if (write(fd, r, sizeof(*r)) != (ssize_t)sizeof(*r)) { perror("write"); exit(1); }
}

/* The four-step protocol: journal write, journal commit, checkpoint, free. */
int commit_transaction(int jfd, int dfd, int txid, int block_num, const char *data) {
    Record tb  = { txid, "TxB", -1, {0} };
    Record upd = { txid, "UPD", block_num, {0} };
    Record te  = { txid, "TxE", -1, {0} };
    strncpy(upd.data, data, PAYLOAD - 1);

    write_record(jfd, &tb);
    write_record(jfd, &upd);
    if (fsync(jfd) != 0) return -1;              /* journal write: TxB + contents durable */

    write_record(jfd, &te);
    if (fsync(jfd) != 0) return -1;              /* journal commit: TxE durable -> committed */

    if (pwrite(dfd, upd.data, PAYLOAD, (off_t)block_num * BLOCK) < 0) return -1;
    if (fsync(dfd) != 0) return -1;               /* checkpoint: final location updated */

    return 0;                                      /* free: superblock update, done later */
}

int main(void) {
    int jfd = open("/tmp/cengdaily_journal.img", O_RDWR | O_CREAT | O_TRUNC, 0600);
    int dfd = open("/tmp/cengdaily_disk.img", O_RDWR | O_CREAT | O_TRUNC, 0600);
    if (jfd < 0 || dfd < 0) { perror("open"); return 1; }

    if (commit_transaction(jfd, dfd, 1, 500, "block 500, committed then checkpointed") != 0) {
        perror("commit"); return 1;
    }
    printf("transaction 1 committed and checkpointed\n");

    char buf[PAYLOAD] = {0};
    if (pread(dfd, buf, PAYLOAD, 500 * BLOCK) < 0) { perror("pread"); return 1; }
    printf("disk block 500 after checkpoint: \"%s\"\n", buf);

    close(jfd); close(dfd);
    return 0;
}
